// Package greeter is a small example showing how to structure code so it can
// be tested with testify's assert, require, and mock packages.
package greeter

import (
	"errors"
	"fmt"
)

// ErrEmptyName is returned when Greet is called with an empty name.
var ErrEmptyName = errors.New("greeter: name must not be empty")

// NameStore looks up display names by user ID. Depending on this interface
// rather than a concrete type lets tests substitute a mock.
type NameStore interface {
	DisplayName(userID string) (string, error)
}

// Greeter builds greetings for users.
type Greeter struct {
	store NameStore
}

// New returns a Greeter backed by store.
func New(store NameStore) *Greeter {
	return &Greeter{store: store}
}

// Greet returns a greeting for the user with the given ID.
func (g *Greeter) Greet(userID string) (string, error) {
	name, err := g.store.DisplayName(userID)
	if err != nil {
		return "", fmt.Errorf("greeter: looking up %q: %w", userID, err)
	}
	if name == "" {
		return "", ErrEmptyName
	}
	return "Hello, " + name + "!", nil
}
EOF
cat > greeter/greeter_test.go <<'EOF'
package greeter

import (
	"errors"
	"testing"

	"github.com/stretchr/testify/assert"
	"github.com/stretchr/testify/mock"
	"github.com/stretchr/testify/require"
)

// mockNameStore is a testify mock implementing NameStore.
type mockNameStore struct {
	mock.Mock
}

func (m *mockNameStore) DisplayName(userID string) (string, error) {
	args := m.Called(userID)
	return args.String(0), args.Error(1)
}

func TestGreet(t *testing.T) {
	store := new(mockNameStore)
	store.On("DisplayName", "u1").Return("Ada", nil).Once()

	got, err := New(store).Greet("u1")

	require.NoError(t, err) // stop the test immediately on failure
	assert.Equal(t, "Hello, Ada!", got)
	store.AssertExpectations(t)
}

func TestGreetErrors(t *testing.T) {
	lookupErr := errors.New("not found")

	tests := []struct {
		name    string
		retName string
		retErr  error
		wantErr error
	}{
		{name: "store error is wrapped", retErr: lookupErr, wantErr: lookupErr},
		{name: "empty name", retName: "", wantErr: ErrEmptyName},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			store := new(mockNameStore)
			store.On("DisplayName", mock.AnythingOfType("string")).Return(tt.retName, tt.retErr)

			got, err := New(store).Greet("u2")

			assert.ErrorIs(t, err, tt.wantErr)
			assert.Empty(t, got)
			store.AssertExpectations(t)
		})
	}
}
EOF
